#!/usr/bin/env node

/**
 * Tutorials Manifest Generator
 *
 * Scans public/tutorials/ for .mdx/.md files, parses frontmatter, and
 * writes public/tutorials-manifest.json with the TUTORIALS list only.
 *
 * Course / series metadata is NOT generated by this script. It lives in
 * the application's data layer (src/lib/courses-store.ts), which seeds
 * itself from data/seed-courses.json on first run and then persists
 * changes to localStorage (web) or Tauri Store (desktop). This keeps
 * the desktop and website versions reading from the same data shape
 * and avoids hardcoding course definitions in source code.
 *
 * Customize the folder / manifest names by editing
 * src/lib/tutorial-config.ts (or by setting the matching env vars before
 * running this script).
 */

import { readdirSync, readFileSync, writeFileSync, existsSync, mkdirSync } from "fs";
import { join, dirname } from "path";
import { fileURLToPath } from "url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const PROJECT_ROOT = join(__dirname, "..");

// Defaults — overridden by env vars to keep the script in sync with
// src/lib/tutorial-config.ts. Edit the env vars (or the TS config) rather
// than these literals if you need to customize.
const TUTORIALS_DIR = join(
  PROJECT_ROOT,
  "public",
  process.env.NEXT_PUBLIC_TUTORIALS_DIR ?? "tutorials"
);
const MANIFEST_PATH = join(
  PROJECT_ROOT,
  "public",
  process.env.NEXT_PUBLIC_TUTORIALS_MANIFEST ?? "tutorials-manifest.json"
);
const TUTORIALS_DIR_NAME =
  process.env.NEXT_PUBLIC_TUTORIALS_DIR ?? "tutorials";

// ─── Helpers ──────────────────────────────────────────────

function parseFrontmatter(content) {
  const match = content.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n([\s\S]*)$/);
  if (!match) return { frontmatter: {}, body: content };

  const yamlText = match[1];
  const frontmatter = {};

  for (const line of yamlText.split("\n")) {
    const idx = line.indexOf(":");
    if (idx > 0) {
      const key = line.slice(0, idx).trim();
      let value = line.slice(idx + 1).trim();
      if (
        typeof value === "string" &&
        ((value.startsWith('"') && value.endsWith('"')) ||
          (value.startsWith("'") && value.endsWith("'")))
      ) {
        value = value.slice(1, -1);
      }
      if (typeof value === "string" && value.startsWith("[") && value.endsWith("]")) {
        try {
          value = JSON.parse(value.replace(/'/g, '"'));
        } catch {
          // keep as string
        }
      }
      if (typeof value === "string" && /^-?\d+$/.test(value)) {
        value = parseInt(value, 10);
      }
      frontmatter[key] = value;
    }
  }

  return { frontmatter, body: match[2] };
}

function scanTutorialsDir() {
  if (!existsSync(TUTORIALS_DIR)) {
    console.log(`⚠️  public/${TUTORIALS_DIR_NAME}/ directory not found, creating empty manifest`);
    mkdirSync(TUTORIALS_DIR, { recursive: true });
    return [];
  }

  const files = readdirSync(TUTORIALS_DIR);
  const tutorialFiles = files.filter(
    (f) => (f.endsWith(".mdx") || f.endsWith(".md")) && !f.startsWith("_")
  );

  const tutorials = [];

  for (const filename of tutorialFiles) {
    const slug = filename.replace(/\.(md|mdx)$/, "");
    const filePath = join(TUTORIALS_DIR, filename);
    const content = readFileSync(filePath, "utf-8");
    const { frontmatter } = parseFrontmatter(content);

    tutorials.push({
      slug,
      title: frontmatter.title || slug,
      description: frontmatter.description || "",
      difficulty: frontmatter.difficulty || "beginner",
      duration: frontmatter.duration || 10,
      category: frontmatter.category || "general",
      tags: Array.isArray(frontmatter.tags) ? frontmatter.tags : [],
      source: "builtin",
      localPath: `/${TUTORIALS_DIR_NAME}/${filename}`,
      sources: Array.isArray(frontmatter.sources) ? frontmatter.sources : undefined,
    });
  }

  // Sort by category then title for consistent ordering
  tutorials.sort((a, b) => {
    if (a.category !== b.category) return a.category.localeCompare(b.category);
    return a.title.localeCompare(b.title);
  });

  return tutorials;
}

// ─── Main ──────────────────────────────────────────────────

console.log(`🔍 Scanning public/${TUTORIALS_DIR_NAME}/ for tutorial files...`);

const tutorials = scanTutorialsDir();

const manifest = {
  generatedAt: new Date().toISOString(),
  count: tutorials.length,
  tutorials,
  // No "series" key — courses live in the data layer (see
  // src/lib/courses-store.ts and data/seed-courses.json).
};

writeFileSync(MANIFEST_PATH, JSON.stringify(manifest, null, 2), "utf-8");

console.log(`✅ Generated manifest with ${tutorials.length} tutorials (no series in manifest).`);
for (const t of tutorials) {
  console.log(`   ${t.slug} (${t.difficulty}, ${t.category})`);
}
console.log(`📝 Manifest written to: public/${TUTORIALS_DIR_NAME}-manifest.json`);
console.log(`ℹ️  Course metadata is loaded from the data layer (data/seed-courses.json).`);
